  ($pp$Bon Tempe Lake$pp$, $pp$bon-tempe-lake$pp$, $pp$trail$pp$::public.place_type, $pp$Marin Municipal Water District (Marin Water)$pp$, 37.9526, -122.6065, $pp$north_bay$pp$::public.region, $pp$Fairfax$pp$, $pp$leash_required$pp$::public.dog_status, $pp$Dogs are welcome on the watershed but must be leashed and under the owner's control at all times. Marin Water discourages aggressive dogs. No boating or swimming in any Marin Water reservoir or stream. The watershed is open daily from 7 a.m. to sunset.$pp$, null, $pp$https://marinwater.org/mt-tam-watershed/visitor-information/$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-16$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz),
  ($pp$Phoenix Lake$pp$, $pp$phoenix-lake$pp$, $pp$trail$pp$::public.place_type, $pp$Marin Municipal Water District (Marin Water)$pp$, 37.9535, -122.5742, $pp$north_bay$pp$::public.region, $pp$Ross$pp$, $pp$leash_required$pp$::public.dog_status, $pp$Dogs are welcome on the watershed but must be leashed and under the owner's control at all times. Marin Water discourages aggressive dogs. No boating or swimming in any Marin Water reservoir or stream. The watershed is open daily from 7 a.m. to sunset.$pp$, null, $pp$https://marinwater.org/mt-tam-watershed/visitor-information/$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-16$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz),
  ($pp$Point Reyes National Seashore$pp$, $pp$point-reyes-national-seashore$pp$, $pp$park$pp$::public.place_type, $pp$National Park Service$pp$, 38.0705, -122.9176, $pp$north_bay$pp$::public.region, $pp$Point Reyes Station$pp$, $pp$leash_required$pp$::public.dog_status, $pp$Pets must be on a leash of 6 feet or less at all times. Dogs are allowed on three ocean beaches (Kehoe, Limantour and Point Reyes/Great Beach), on the Kehoe Beach Trail, and on paths and roads in the Niman Ranch/Commonweal area. All other trails in the Seashore are closed to pets, as are Tomales Point Trail, backcountry campgrounds and Tomales Bay's west-side beaches. During western snowy plover nesting (March 1 to September 30) pets are not allowed on the beach south of the Kehoe Beach trail or north of the North Beach parking lot. During elephant seal pupping and mating (January to March) pets and people are barred from the beach south of the historic Navy installation/lifeboat station.$pp$, null, $pp$https://www.nps.gov/pore/planyourvisit/pets.htm$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-16$pp$::date, $pp$claude (official page fetch), pending human review$pp$, $pp$Only a few beaches and one trail allow dogs. Seasonal closures can change, so check the park's Current Conditions page.$pp$, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz),
  ($pp$Kehoe Beach$pp$, $pp$kehoe-beach$pp$, $pp$beach$pp$::public.place_type, $pp$National Park Service$pp$, 38.1549, -122.9489, $pp$north_bay$pp$::public.region, $pp$Point Reyes Station$pp$, $pp$leash_required$pp$::public.dog_status, $pp$Pets are allowed on leash (6 feet or less) on the beach north of the Kehoe Beach trail, and on the Kehoe Beach Trail. During western snowy plover nesting (March 1 to September 30) pets are not allowed on the beach south of the trail.$pp$, null, $pp$https://www.nps.gov/pore/planyourvisit/pets.htm$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-16$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz),
  ($pp$Limantour Beach$pp$, $pp$limantour-beach$pp$, $pp$beach$pp$::public.place_type, $pp$National Park Service$pp$, 38.0244, -122.8791, $pp$north_bay$pp$::public.region, $pp$Point Reyes Station$pp$, $pp$leash_required$pp$::public.dog_status, $pp$Pets are allowed on leash (6 feet or less) on the beach southeast of the parking lot to the beach adjacent to Coast Camp. The page lists this as open year-round, with temporary closures possible.$pp$, null, $pp$https://www.nps.gov/pore/planyourvisit/pets.htm$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-16$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz),
  ($pp$Point Reyes (Great) Beach$pp$, $pp$point-reyes-great-beach$pp$, $pp$beach$pp$::public.place_type, $pp$National Park Service$pp$, 38.0833, -122.9733, $pp$north_bay$pp$::public.region, $pp$Point Reyes Station$pp$, $pp$leash_required$pp$::public.dog_status, $pp$Pets are allowed on leash (6 feet or less) from the North Beach parking lot south to the historic Navy installation/lifeboat station. During western snowy plover nesting (March 1 to September 30) pets are not allowed on the beach south of the Kehoe Beach trail or north of the North Beach parking lot. During elephant seal pupping and mating (January to March) pets and people are barred from the beach south of the historic Navy installation/lifeboat station.$pp$, null, $pp$https://www.nps.gov/pore/planyourvisit/pets.htm$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-16$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz),
  ($pp$Tomales Point Trail$pp$, $pp$tomales-point-trail$pp$, $pp$trail$pp$::public.place_type, $pp$National Park Service$pp$, 38.214, -122.9748, $pp$north_bay$pp$::public.region, $pp$Inverness$pp$, $pp$no_dogs$pp$::public.dog_status, $pp$Pets are not permitted on the Tomales Point Trail.$pp$, null, $pp$https://www.nps.gov/pore/planyourvisit/pets.htm$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-16$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz),
  ($pp$Rodeo Beach$pp$, $pp$rodeo-beach$pp$, $pp$beach$pp$::public.place_type, $pp$Golden Gate National Recreation Area$pp$, 37.8305, -122.5365, $pp$north_bay$pp$::public.region, $pp$Sausalito$pp$, $pp$off_leash_zones$pp$::public.dog_status, $pp$The Superintendent's Compendium lists Rodeo Beach, South Rodeo Beach and Fort Cronkhite for voice-control dog walking.$pp$, $pp$Dogs must be under voice control. Check posted signs for closures.$pp$, $pp$https://www.nps.gov/goga/learn/management/superintendents-compendium.htm$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-16$pp$::date, $pp$claude (official page fetch), pending human review$pp$, $pp$The park's own beach page could not be read, so this comes from the Superintendent's Compendium.$pp$, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz),
  ($pp$Stinson Beach$pp$, $pp$stinson-beach$pp$, $pp$beach$pp$::public.place_type, $pp$Golden Gate National Recreation Area$pp$, 37.8972, -122.6398, $pp$north_bay$pp$::public.region, $pp$Stinson Beach$pp$, $pp$no_dogs$pp$::public.dog_status, $pp$The Superintendent's Compendium closes all Stinson Beach areas to dogs, except that on-leash dog walking is allowed in the parking and picnic areas. Coastal, Dipsea, Matt Davis and McKennan trails and Willow Camp Fire Road are also closed to dogs.$pp$, null, $pp$https://www.nps.gov/goga/learn/management/superintendents-compendium.htm$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-16$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz),
  ($pp$Tennessee Valley$pp$, $pp$tennessee-valley$pp$, $pp$trail$pp$::public.place_type, $pp$Golden Gate National Recreation Area$pp$, 37.8603, -122.5364, $pp$north_bay$pp$::public.region, $pp$Mill Valley$pp$, $pp$no_dogs$pp$::public.dog_status, $pp$Dogs, even on leash, are not allowed on the Tennessee Valley Trail or on any other trail in Tennessee Valley, except the Coastal Trail. Dog walking is allowed on leash on the Miwok Trail from the Tennessee Valley parking area north to Highway 101.$pp$, null, $pp$https://www.nps.gov/goga/planyourvisit/tennessee_valley.htm$pp$, $pp$verified$pp$::public.verification_status, $pp$2026-11-16$pp$::date, $pp$claude (official page fetch), pending human review$pp$, null, 90, $pp$editorial$pp$, '{}'::text[], null, null, null, null, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz, $pp$2026-11-16T00:00:00.000Z$pp$::timestamptz),
