  ($pp$point-isabel$pp$, $pp${"src":"/photos/point-isabel.jpg","alt":"Dirt path and cypress trees near the entrance of Point Isabel Regional Shoreline","credit":"Ndołkah","license":"CC BY-SA 4.0","source_url":"https://commons.wikimedia.org/wiki/File:Pointislabelregionalshoreline2019.jpg","license_url":"https://creativecommons.org/licenses/by-sa/4.0"}$pp$, $pp${"trails":[],"park_wide":["The park page mentions more than 2.5 miles of San Francisco Bay Trail in the vicinity of the park.","Dogs must be on a leash in parking lots and streets."],"sources":[{"label":"East Bay Regional Park District: Point Isabel","url":"https://www.ebparks.org/parks/point-isabel"}],"verified_on":"2026-11-15"}$pp$),
  ($pp$tilden$pp$, $pp${"src":"/photos/tilden.jpg","alt":"Hazy hills and trees seen from Selby Trail in Tilden Regional Park","credit":"Mliu92","license":"CC BY-SA 3.0","source_url":"https://commons.wikimedia.org/wiki/File:Tilden_Regional_Park_5.jpg","license_url":"https://creativecommons.org/licenses/by-sa/3.0"}$pp$, $pp${"trails":[],"park_wide":["The park page says there are 39.41 miles of trails in Tilden Park. That is all trails, not only ones open to dogs.","Dogs must be on a leash on Nimitz Way.","Dogs are not allowed in the swim facility at Lake Anza."],"sources":[{"label":"East Bay Regional Park District: Tilden","url":"https://www.ebparks.org/parks/tilden"}],"verified_on":"2026-11-15"}$pp$),
